/** Public entry point — the only module consumers/docs should import from. */

export { DataGridViews, type DataGridViewsLabels, type DataGridViewsProps } from "./views-menu";
export {
  useDataGridViews,
  type ImportViewResult,
  type UseDataGridViewsOptions,
  type UseDataGridViewsResult,
} from "./use-data-grid-views";
export { createLocalStorageViewsStorage, createMemoryViewsStorage, type DataGridViewsStorage } from "./view-storage";
export type { DataGridView, DataGridViewState, DataGridViewsDocument } from "./view-state";

"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import {
  useDataGridActions,
  useDataGridAllColumns,
  useDataGridFilterState,
  useDataGridSearchText,
  useDataGridSortState,
} from "@/registry/default/components/data-grid/data-grid";
import { resolveCustomFilterOperators, useDataGridSelector, useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import {
  MAX_DOCUMENT_LENGTH,
  MAX_VIEW_FILE_LENGTH,
  MAX_VIEWS,
  captureViewState,
  cleanViewName,
  emptyViewsDocument,
  parseViewDocument,
  parseViewFile,
  sanitizeViewState,
  savableViewState,
  serializeViewFile,
  viewPartKeys,
  viewStateKey,
  type DataGridView,
  type DataGridViewState,
  type DataGridViewsDocument,
  type ViewColumns,
} from "./view-state";
import { createLocalStorageViewsStorage, type DataGridViewsStorage } from "./view-storage";

/** Options for {@link useDataGridViews}. */
export type UseDataGridViewsOptions = {
  /**
   * Where views persist. Default: `localStorage` under `storageKey`. The first load reads it once;
   * a new `storageKey` loads again. Remount the grid with a new `key` to switch to another
   * `storage` object, for example another user's.
   */
  storage?: DataGridViewsStorage;
  /** `localStorage` key of the default storage; ignored when `storage` is set. Default `"gridcn-views"`. */
  storageKey?: string;
  /** Id of the active view. Controlled: the hook opens a view when this changes, and picks only call `onValueChange`. */
  value?: string | null;
  /** First active view id when `value` is not set. */
  defaultValue?: string | null;
  onValueChange?: (id: string | null) => void;
  /** Open the default view after load when the grid still holds its start state and `value` and `defaultValue` are unset. Default `true`. */
  enableDefaultView?: boolean;
  /** Called with a load or save failure. */
  onError?: (error: unknown) => void;
};

export type ImportViewResult =
  | { ok: true; view: DataGridView; dropped: number }
  | { ok: false; reason: "too-large" | "invalid" | "limit" | "loading" };

/** Result of {@link useDataGridViews}. */
export type UseDataGridViewsResult = {
  views: readonly DataGridView[];
  activeViewId: string | null;
  activeView: DataGridView | null;
  /** The grid differs from the active view. */
  modified: boolean;
  /** The grid state exceeds a view limit (1,000 characters per filter value, 1,000 list entries, 16 sorts, 500 search characters), so `saveView` returns `null` and `updateView` returns `false`. */
  overLimit: boolean;
  defaultViewId: string | null;
  /** The stored views are being read. */
  loading: boolean;
  /** A save is in flight. */
  saving: boolean;
  /** The latest load or save failure, else `null`. */
  error: unknown;
  /** Which request `error` belongs to. */
  failed: "load" | "save" | null;
  /** Repeats the failed load or save. Stable. */
  retry: () => void;
  /** Opens a view (again, to revert changes) and makes it active; `null` only clears the active view. With a controlled `value`, a pick only calls `onValueChange`. */
  selectView: (id: string | null) => void;
  /** Saves the grid state under `name` (trimmed, at most 80 characters) and makes the new view active. `null` for a blank name, the limit of 50 views, a grid state over a view limit (see `overLimit`), or before the load ends. */
  saveView: (name: string) => DataGridView | null;
  /** Replaces a view's state with the grid state. Default: the active view. `false` for an unknown id, no active view, a grid state over a view limit (see `overLimit`), or before the load ends. */
  updateView: (id?: string) => boolean;
  /** Renames a view. `false` for an unknown id, a blank name, or before the load ends. */
  renameView: (id: string, name: string) => boolean;
  /** Deletes a view; deleting the active view clears it, and deleting the default view clears the default. `false` for an unknown id or before the load ends. */
  deleteView: (id: string) => boolean;
  /** Makes a view the one opened after load; `null` clears it. `false` for an unknown id or before the load ends. */
  setDefaultView: (id: string | null) => boolean;
  /** The view as JSON text, or `null` for an unknown id or a view too large to import again. Default: the active view. */
  exportView: (id?: string) => string | null;
  /** Reads JSON from `exportView`, drops what the live columns lack, and saves it as a new active view named `options.name` when the file has none (`"View"` without either). `dropped` counts the removed parts. */
  importView: (text: string, options?: { name?: string }) => ImportViewResult;
};

/** Calls a consumer callback; a throw must not break the hook. */
function callSafely<T>(callback: ((arg: T) => void) | undefined, arg: T): void {
  if (!callback) return;
  try {
    callback(arg);
  } catch (cause) {
    console.error("[data-grid-views] a callback threw", cause);
  }
}

function createViewId(): string {
  return `v${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
}

/**
 * Saves and restores named grid views: sort, filters, search, and column layout. Call it inside the
 * grid provider. Opening a view runs the same store actions as a user gesture, only for the parts
 * that differ, so controlled `sortState` and `filterState` receive their change callbacks.
 */
export function useDataGridViews(options: UseDataGridViewsOptions = {}): UseDataGridViewsResult {
  const { storageKey, value, defaultValue, onValueChange, enableDefaultView = true, onError } = options;
  const defaultStorage = useMemo(() => createLocalStorageViewsStorage(storageKey), [storageKey]);
  const storage = options.storage ?? defaultStorage;

  const storeApi = useDataGridStoreApi();
  const actions = useDataGridActions();
  const allColumns = useDataGridAllColumns();
  const sortState = useDataGridSortState();
  const filterState = useDataGridFilterState();
  const searchText = useDataGridSearchText();
  const searchOptions = useDataGridSelector((s) => s.searchOptions);
  const columnLayout = useDataGridSelector((s) => s.columnLayout);

  const cellTypes = useDataGridSelector((s) => s.cellTypes);
  const registeredOperators = useCallback(
    (column: (typeof allColumns)[number]) => new Map([...resolveCustomFilterOperators(column, column.type ? cellTypes[column.type] : undefined)].map(([id, op]) => [id, op.input ?? "single"] as const)),
    [cellTypes],
  );
  const columnMap: ViewColumns = useMemo(() => new Map(allColumns.map((c) => [c.id, { sortable: c.sortable, filterable: c.filterable, operators: registeredOperators(c) }])), [allColumns, registeredOperators]);
  // opting a column out of sort or filter UI does not stop programmatic specs, so applying a saved view checks ids only
  const knownColumns: ViewColumns = useMemo(() => new Map(allColumns.map((c) => [c.id, { operators: registeredOperators(c) }])), [allColumns, registeredOperators]);
  const latest = useRef({ columnMap, knownColumns, onValueChange, onError, value, enableDefaultView, defaultValue });
  useLayoutEffect(() => {
    latest.current = { columnMap, knownColumns, onValueChange, onError, value, enableDefaultView, defaultValue };
  });

  const [document, setDocument] = useState<DataGridViewsDocument | null>(null);
  const documentRef = useRef<DataGridViewsDocument | null>(null);
  const loaded = document !== null;
  const [internalActiveId, setInternalActiveId] = useState<string | null>(defaultValue ?? null);
  const activeViewId = value !== undefined ? value : internalActiveId;
  const [appliedKey, setAppliedKey] = useState<string | null>(null);
  const appliedIdRef = useRef<string | null | undefined>(undefined);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<unknown>(null);
  const [failed, setFailed] = useState<"load" | "save" | null>(null);
  const failedRef = useRef<"load" | "save" | null>(null);
  const [loadAttempt, setLoadAttempt] = useState(0);
  const pendingSaveRef = useRef<DataGridViewsDocument | null>(null);
  const savingRef = useRef(false);
  const storageRef = useRef(storage);
  useLayoutEffect(() => {
    storageRef.current = storage;
  });

  const readState = useCallback((): DataGridViewState => {
    const s = storeApi.getState();
    return captureViewState({ sorts: s.sortState, filters: s.filterState, searchText: s.searchText, searchOptions: s.searchOptions, columnLayout: s.columnLayout });
  }, [storeApi]);

  const readSavableState = useCallback(() => savableViewState(readState()), [readState]);

  const reportError = useCallback((kind: "load" | "save", cause: unknown) => {
    failedRef.current = kind;
    setError(cause);
    setFailed(kind);
    callSafely(latest.current.onError, cause);
  }, []);

  const clearError = useCallback(() => {
    failedRef.current = null;
    setError(null);
    setFailed(null);
  }, []);

  const applyState = useCallback(
    (state: DataGridViewState) => {
      const clean = sanitizeViewState(state, latest.current.knownColumns).state;
      const wanted = viewPartKeys(clean);
      const now = viewPartKeys(readState());
      if (wanted.sorts !== now.sorts) actions.setSorts(clean.sorts);
      if (wanted.filters !== now.filters) actions.setFilters(clean.filters);
      if (wanted.search !== now.search) actions.setSearch(clean.searchText, clean.searchOptions);
      if (wanted.layout !== now.layout) actions.setColumnLayout(clean.columnLayout);
      // the store fills in layout parts a view leaves out, so the baseline reads the layout back
      setAppliedKey(viewStateKey({ ...clean, columnLayout: storeApi.getState().columnLayout }));
    },
    [actions, readState, storeApi],
  );

  const notify = useCallback((id: string | null) => callSafely(latest.current.onValueChange, id), []);

  /** Makes `id` active for a state the grid already holds. */
  const setActive = useCallback(
    (id: string | null) => {
      appliedIdRef.current = id;
      if (latest.current.value === undefined) setInternalActiveId(id);
      notify(id);
    },
    [notify],
  );

  const flushSaves = useCallback(async () => {
    if (savingRef.current) return;
    savingRef.current = true;
    setSaving(true);
    while (pendingSaveRef.current) {
      const next = pendingSaveRef.current;
      pendingSaveRef.current = null;
      if (JSON.stringify(next).length > MAX_DOCUMENT_LENGTH) {
        reportError("save", new Error("The saved views are too large to store"));
        continue;
      }
      try {
        await storageRef.current.save(next);
        clearError();
      } catch (cause) {
        reportError("save", cause);
      }
    }
    savingRef.current = false;
    setSaving(false);
  }, [clearError, reportError]);

  const commit = useCallback(
    (next: DataGridViewsDocument) => {
      documentRef.current = next;
      setDocument(next);
      pendingSaveRef.current = next;
      void flushSaves();
    },
    [flushSaves],
  );

  const loadedKeyRef = useRef(storageKey);
  useEffect(() => {
    const controller = new AbortController();
    documentRef.current = null;
    setDocument(null);
    if (loadedKeyRef.current !== storageKey) {
      loadedKeyRef.current = storageKey;
      appliedIdRef.current = undefined;
      if (latest.current.value === undefined) setInternalActiveId(null);
      notify(null);
    }
    void (async () => {
      let raw: unknown;
      try {
        raw = await storageRef.current.load({ signal: controller.signal });
      } catch (cause) {
        if (!controller.signal.aborted) reportError("load", cause);
        return;
      }
      if (controller.signal.aborted) return;
      const parsed = raw == null ? emptyViewsDocument() : parseViewDocument(raw);
      if (!parsed) {
        reportError("load", new Error("The saved views are in an unknown format"));
        return;
      }
      documentRef.current = parsed;
      setDocument(parsed);
      clearError();
      const { value: controlled, defaultValue: seed, enableDefaultView: useDefault } = latest.current;
      const initial = storeApi.getInitialState();
      const untouched =
        viewStateKey(readState()) ===
        viewStateKey(captureViewState({ sorts: initial.sortState, filters: initial.filterState, searchText: initial.searchText, searchOptions: initial.searchOptions, columnLayout: initial.columnLayout }));
      const view = useDefault && controlled === undefined && seed === undefined && untouched ? parsed.views.find((v) => v.id === parsed.defaultViewId) : undefined;
      if (view) {
        applyState(view.state);
        setActive(view.id);
      }
    })();
    return () => controller.abort();
  }, [storageKey, loadAttempt, storeApi, readState, applyState, setActive, notify, reportError, clearError]);

  useEffect(() => {
    if (!loaded || appliedIdRef.current === activeViewId) return;
    appliedIdRef.current = activeViewId;
    const view = documentRef.current?.views.find((v) => v.id === activeViewId);
    if (view) applyState(view.state);
  }, [loaded, activeViewId, applyState]);

  const views = document?.views ?? EMPTY_VIEWS;
  const activeView = views.find((v) => v.id === activeViewId) ?? null;

  const currentKey = useMemo(
    () => (activeView ? viewStateKey({ sorts: sortState, filters: filterState, searchText, searchOptions, columnLayout }) : null),
    [activeView, sortState, filterState, searchText, searchOptions, columnLayout],
  );

  const overLimit = useMemo(
    () => savableViewState(captureViewState({ sorts: sortState, filters: filterState, searchText, searchOptions, columnLayout })) === null,
    [sortState, filterState, searchText, searchOptions, columnLayout],
  );

  const activeIdNow = useCallback(() => (latest.current.value !== undefined ? latest.current.value : appliedIdRef.current) ?? null, []);

  const selectView = useCallback(
    (id: string | null) => {
      const view = id === null ? undefined : documentRef.current?.views.find((v) => v.id === id);
      if (id !== null && !view) return;
      const controlled = latest.current.value !== undefined;
      if (controlled) {
        if (view && latest.current.value === id) applyState(view.state);
        else notify(id);
        return;
      }
      if (view) applyState(view.state);
      setActive(id);
    },
    [applyState, notify, setActive],
  );

  const saveView = useCallback(
    (name: string) => {
      const current = documentRef.current;
      const clean = cleanViewName(name);
      if (!current || clean === "" || current.views.length >= MAX_VIEWS) return null;
      const state = readSavableState();
      if (!state) return null;
      const view: DataGridView = { id: createViewId(), name: clean, state };
      commit({ ...current, views: [...current.views, view] });
      setAppliedKey(viewStateKey(view.state));
      setActive(view.id);
      return view;
    },
    [commit, readSavableState, setActive],
  );

  const updateView = useCallback(
    (id?: string) => {
      const current = documentRef.current;
      const targetId = id ?? activeIdNow();
      if (!current || !targetId || !current.views.some((v) => v.id === targetId)) return false;
      const state = readSavableState();
      if (!state) return false;
      commit({ ...current, views: current.views.map((v) => (v.id === targetId ? { ...v, state } : v)) });
      if (targetId === activeIdNow()) setAppliedKey(viewStateKey(state));
      return true;
    },
    [activeIdNow, commit, readSavableState],
  );

  const renameView = useCallback(
    (id: string, name: string) => {
      const current = documentRef.current;
      const clean = cleanViewName(name);
      if (!current || clean === "" || !current.views.some((v) => v.id === id)) return false;
      commit({ ...current, views: current.views.map((v) => (v.id === id ? { ...v, name: clean } : v)) });
      return true;
    },
    [commit],
  );

  const deleteView = useCallback(
    (id: string) => {
      const current = documentRef.current;
      if (!current || !current.views.some((v) => v.id === id)) return false;
      commit({ ...current, views: current.views.filter((v) => v.id !== id), defaultViewId: current.defaultViewId === id ? null : current.defaultViewId });
      if (activeIdNow() === id) setActive(null);
      return true;
    },
    [activeIdNow, commit, setActive],
  );

  const setDefaultView = useCallback(
    (id: string | null) => {
      const current = documentRef.current;
      if (!current || (id !== null && !current.views.some((v) => v.id === id))) return false;
      commit({ ...current, defaultViewId: id });
      return true;
    },
    [commit],
  );

  const exportView = useCallback(
    (id?: string) => {
      const targetId = id ?? activeIdNow();
      const view = documentRef.current?.views.find((v) => v.id === targetId);
      if (!view) return null;
      const text = serializeViewFile(view);
      return text.length > MAX_VIEW_FILE_LENGTH ? null : text;
    },
    [activeIdNow],
  );

  const importView = useCallback(
    (text: string, importOptions?: { name?: string }): ImportViewResult => {
      const current = documentRef.current;
      if (!current) return { ok: false, reason: "loading" };
      if (current.views.length >= MAX_VIEWS) return { ok: false, reason: "limit" };
      const parsed = parseViewFile(text, latest.current.columnMap);
      if (!parsed.ok) return parsed;
      const view: DataGridView = { id: createViewId(), name: parsed.name || cleanViewName(importOptions?.name) || "View", state: parsed.state };
      commit({ ...current, views: [...current.views, view] });
      applyState(view.state);
      setActive(view.id);
      return { ok: true, view, dropped: parsed.dropped };
    },
    [applyState, commit, setActive],
  );

  const retry = useCallback(() => {
    if (failedRef.current === "load") setLoadAttempt((n) => n + 1);
    else if (failedRef.current === "save" && documentRef.current) {
      pendingSaveRef.current = documentRef.current;
      void flushSaves();
    }
  }, [flushSaves]);

  return {
    views,
    activeViewId,
    activeView,
    modified: currentKey !== null && appliedKey !== null && currentKey !== appliedKey,
    overLimit,
    defaultViewId: document?.defaultViewId ?? null,
    loading: document === null && failed !== "load",
    saving,
    error,
    failed,
    retry,
    selectView,
    saveView,
    updateView,
    renameView,
    deleteView,
    setDefaultView,
    exportView,
    importView,
  };
}

const EMPTY_VIEWS: readonly DataGridView[] = [];

import type { ColumnLayout, BuiltInFilterOperator, FilterNode, FilterOperator, FilterOperatorInput, FilterSpec, SearchOptions, SortSpec } from "@/registry/default/components/data-grid/data-grid";
import { MAX_FILTER_GROUP_DEPTH, countFilterSpecs, isFilterGroup, pruneFilterSpecs } from "@/registry/default/components/data-grid/data-grid-sdk";

export const MAX_VIEWS = 50;
/** Largest stored document, in characters; a save over it is refused so the next load can read it. */
export const MAX_DOCUMENT_LENGTH = 1_000_000;
export const MAX_VIEW_NAME_LENGTH = 80;
/** Largest view file `parseViewFile` reads, in characters. */
export const MAX_VIEW_FILE_LENGTH = 100_000;
const MAX_SORTS = 16;
const MAX_FILTERS = 64;
const MAX_FILTER_GROUPS = 16;
const MAX_LIST_ENTRIES = 1000;
const MAX_TEXT_LENGTH = 1000;
const MAX_SEARCH_LENGTH = 500;
const MAX_LAYOUT_ENTRIES = 1000;
const MAX_COLUMN_ID_LENGTH = 200;
const MAX_COLUMN_WIDTH = 10_000;
const MAX_VIEW_ID_LENGTH = 64;
const FILE_FORMAT = "gridcn-view";

/** The grid state a saved view restores. */
export type DataGridViewState = {
  sorts: SortSpec[];
  filters: FilterNode[];
  searchText: string;
  searchOptions: Required<SearchOptions>;
  columnLayout: ColumnLayout;
};

export type DataGridView = { id: string; name: string; state: DataGridViewState };

/** What a storage adapter persists. */
export type DataGridViewsDocument = { version: 1; views: DataGridView[]; defaultViewId: string | null };

/** The live columns a view is checked against; `undefined` accepts every id (structure only). */
export type ViewColumns = ReadonlyMap<string, { sortable?: boolean; filterable?: boolean; operators?: ReadonlyMap<string, FilterOperatorInput> }>;

export type ViewFileResult = { ok: true; name: string; state: DataGridViewState; dropped: number } | { ok: false; reason: "too-large" | "invalid" };

const OPERATORS = [
  "contains",
  "notContains",
  "equals",
  "notEquals",
  "startsWith",
  "endsWith",
  "empty",
  "notEmpty",
  "gt",
  "gte",
  "lt",
  "lte",
  "isBetween",
  "isAnyOf",
  "isNoneOf",
] as const satisfies readonly BuiltInFilterOperator[];

/** Fails to compile when a built-in operator is missing from `OPERATORS`, which would drop saved filters silently. */
const operatorsAreExhaustive: Exclude<BuiltInFilterOperator, (typeof OPERATORS)[number]> extends never ? true : never = true;
void operatorsAreExhaustive;

const FILTER_OPERATOR_IDS: ReadonlySet<string> = new Set(OPERATORS);
const MAX_OPERATOR_ID_LENGTH = 64;

export function emptyViewState(): DataGridViewState {
  return { sorts: [], filters: [], searchText: "", searchOptions: { matchCase: false, wholeCell: false }, columnLayout: { widths: {}, order: [], pins: {}, hidden: [] } };
}

export function emptyViewsDocument(): DataGridViewsDocument {
  return { version: 1, defaultViewId: null, views: [] };
}

function stripFilterIds(nodes: readonly FilterNode[], depth: number): FilterNode[] {
  const out: FilterNode[] = [];
  for (const node of nodes) {
    if (isFilterGroup(node)) {
      if (depth < MAX_FILTER_GROUP_DEPTH) out.push({ join: node.join, filters: stripFilterIds(node.filters, depth + 1) });
    } else {
      const { filterId: _filterId, ...spec } = node;
      out.push(spec);
    }
  }
  return out;
}

/** Copies grid state into a view state without the transient `filterId`s. */
export function captureViewState(source: DataGridViewState): DataGridViewState {
  const { widths, order, pins, hidden } = source.columnLayout;
  return {
    sorts: source.sorts.map((s) => ({ columnId: s.columnId, direction: s.direction })),
    filters: stripFilterIds(source.filters, 0),
    searchText: source.searchText,
    searchOptions: { matchCase: source.searchOptions.matchCase, wholeCell: source.searchOptions.wholeCell },
    columnLayout: { widths: { ...widths }, order: [...order], pins: { ...pins }, hidden: [...hidden] },
  };
}

function withoutUnusedValues(nodes: readonly FilterNode[]): FilterNode[] {
  return nodes.map((node) => {
    if (isFilterGroup(node)) return { join: node.join, filters: withoutUnusedValues(node.filters) };
    return node.operator === "empty" || node.operator === "notEmpty" ? { columnId: node.columnId, operator: node.operator } : node;
  });
}

function sortKeys(_key: string, value: unknown): unknown {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return value;
  return Object.fromEntries(Object.entries(value).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)));
}

/** One string per part of a state; equal strings mean the part restores the same grid. */
export function viewPartKeys(state: DataGridViewState): { sorts: string; filters: string; search: string; layout: string } {
  // lossless except for the one thing storage drops: the unused `value` of `empty` and `notEmpty`
  const captured = captureViewState(state);
  captured.filters = withoutUnusedValues(captured.filters);
  captured.columnLayout.hidden.sort();
  return {
    sorts: JSON.stringify(captured.sorts),
    filters: JSON.stringify(captured.filters, sortKeys),
    search: JSON.stringify([captured.searchText, captured.searchOptions]),
    layout: JSON.stringify(captured.columnLayout, sortKeys),
  };
}

/** A string that is equal for two states that restore the same view. */
export function viewStateKey(state: DataGridViewState): string {
  return Object.values(viewPartKeys(state)).join("|");
}

/** The state in the form that reloads unchanged, or `null` when a view limit would cut or drop part of it. */
export function savableViewState(state: DataGridViewState): DataGridViewState | null {
  const clean = sanitizeViewState(state, undefined).state;
  return viewStateKey(clean) === viewStateKey(state) ? clean : null;
}

type RawSort = { columnId?: unknown; direction?: unknown };
type RawFilter = { columnId?: unknown; operator?: unknown; value?: unknown; join?: unknown; filters?: unknown };
type RawLayout = { widths?: unknown; order?: unknown; pins?: unknown; hidden?: unknown };
type RawState = { sorts?: unknown; filters?: unknown; searchText?: unknown; searchOptions?: unknown; columnLayout?: unknown };
type RawSearchOptions = { matchCase?: unknown; wholeCell?: unknown };
type RawView = { id?: unknown; name?: unknown; state?: unknown };
type RawDocument = { version?: unknown; views?: unknown; defaultViewId?: unknown };
type RawFile = { format?: unknown; version?: unknown; name?: unknown; state?: unknown };

/** Narrows untrusted JSON to a plain object whose fields are all `unknown`. */
function asRecord<T extends object>(value: unknown): T | undefined {
  return typeof value === "object" && value !== null && !Array.isArray(value) ? (value as T) : undefined;
}

/** Counts the entries beyond `cap` as dropped, then returns the first `cap`. */
function boundedEntries<T>(entries: readonly T[], cap: number, tally: { dropped: number }): readonly T[] {
  if (entries.length > cap) tally.dropped += entries.length - cap;
  return entries.slice(0, cap);
}

function acceptsColumnId(id: unknown, columns: ViewColumns | undefined): id is string {
  if (typeof id !== "string" || id === "" || id.length > MAX_COLUMN_ID_LENGTH || id === "__proto__") return false;
  return columns === undefined || columns.has(id);
}

function sanitizeSorts(raw: unknown, columns: ViewColumns | undefined, tally: { dropped: number }): SortSpec[] {
  if (!Array.isArray(raw)) return [];
  const sorts: SortSpec[] = [];
  const seen = new Set<string>();
  for (const item of boundedEntries(raw, MAX_LIST_ENTRIES, tally)) {
    const entry = asRecord<RawSort>(item);
    const columnId = entry?.columnId;
    const direction = entry?.direction;
    if (!acceptsColumnId(columnId, columns) || columns?.get(columnId)?.sortable === false || (direction !== "asc" && direction !== "desc") || seen.has(columnId) || sorts.length >= MAX_SORTS) {
      tally.dropped++;
      continue;
    }
    seen.add(columnId);
    sorts.push({ columnId, direction });
  }
  return sorts;
}

type FilterBudget = { leaves: number; groups: number };

function sanitizeFilterValue(operator: string, raw: unknown, tally: { dropped: number }): { ok: true; value: FilterSpec["value"] } | { ok: false } {
  const text = (v: unknown): v is string => typeof v === "string" && v.length <= MAX_TEXT_LENGTH;
  if (operator === "empty" || operator === "notEmpty") return { ok: true, value: undefined };
  if (operator === "isBetween") return Array.isArray(raw) && raw.length === 2 && text(raw[0]) && text(raw[1]) ? { ok: true, value: [raw[0], raw[1]] } : { ok: false };
  if (operator === "isAnyOf" || operator === "isNoneOf") {
    if (!Array.isArray(raw) || !raw.every(text)) return { ok: false };
    // a truncated exclusion list would match more rows than the view meant
    if (raw.length > MAX_LIST_ENTRIES) {
      if (operator === "isNoneOf") return { ok: false };
      tally.dropped += raw.length - MAX_LIST_ENTRIES;
      return { ok: true, value: raw.slice(0, MAX_LIST_ENTRIES) };
    }
    return { ok: true, value: [...raw] };
  }
  return text(raw) ? { ok: true, value: raw } : { ok: false };
}

function sanitizeCustomValue(input: FilterOperatorInput | "any", raw: unknown): { ok: true; value: FilterSpec["value"] } | { ok: false } {
  const text = (v: unknown): v is string => typeof v === "string" && v.length <= MAX_TEXT_LENGTH;
  if (input === "none") return { ok: true, value: undefined };
  if (input === "single") return text(raw) ? { ok: true, value: raw } : { ok: false };
  if (input === "range") return Array.isArray(raw) && raw.length === 2 && text(raw[0]) && text(raw[1]) ? { ok: true, value: [raw[0], raw[1]] } : { ok: false };
  if (input === "list" || Array.isArray(raw)) {
    if (!Array.isArray(raw) || !raw.every(text)) return { ok: false };
    if (raw.length > MAX_LIST_ENTRIES) return { ok: false };
    return { ok: true, value: [...raw] };
  }
  if (raw === undefined) return { ok: true, value: undefined };
  return text(raw) ? { ok: true, value: raw } : { ok: false };
}

function sanitizeOperatorValue(operator: unknown, columnId: unknown, raw: unknown, columns: ViewColumns | undefined, tally: { dropped: number }): { ok: true; value: FilterSpec["value"] } | { ok: false } {
  if (typeof operator !== "string") return { ok: false };
  if (FILTER_OPERATOR_IDS.has(operator)) return sanitizeFilterValue(operator, raw, tally);
  if (operator.length === 0 || operator.length > MAX_OPERATOR_ID_LENGTH) return { ok: false };
  // a live-grid snapshot has no column map; a column map accepts only operators the column registers
  if (!columns) return sanitizeCustomValue("any", raw);
  const input = typeof columnId === "string" ? columns.get(columnId)?.operators?.get(operator) : undefined;
  return input ? sanitizeCustomValue(input, raw) : { ok: false };
}

function sanitizeFilterNodes(raw: unknown, depth: number, columns: ViewColumns | undefined, budget: FilterBudget, tally: { dropped: number }): FilterNode[] {
  if (!Array.isArray(raw)) return [];
  const out: FilterNode[] = [];
  for (const item of boundedEntries(raw, MAX_FILTERS * 4, tally)) {
    const entry = asRecord<RawFilter>(item);
    if (!entry) {
      tally.dropped++;
      continue;
    }
    if (Array.isArray(entry.filters)) {
      const join = entry.join;
      if ((join !== "and" && join !== "or") || depth >= MAX_FILTER_GROUP_DEPTH || budget.groups >= MAX_FILTER_GROUPS) {
        tally.dropped++;
        continue;
      }
      budget.groups++;
      const children = sanitizeFilterNodes(entry.filters, depth + 1, columns, budget, tally);
      if (children.length === 0) tally.dropped++;
      else out.push({ join, filters: children });
      continue;
    }
    const { columnId, operator } = entry;
    const value = sanitizeOperatorValue(operator, columnId, entry.value, columns, tally);
    if (!acceptsColumnId(columnId, columns) || columns?.get(columnId)?.filterable === false || !value.ok || budget.leaves >= MAX_FILTERS) {
      tally.dropped++;
      continue;
    }
    budget.leaves++;
    const spec: FilterSpec = { columnId, operator: operator as FilterOperator };
    if (value.value !== undefined) spec.value = value.value;
    out.push(spec);
  }
  return out;
}

function sanitizeIdList(raw: unknown, columns: ViewColumns | undefined, tally: { dropped: number }): string[] {
  if (!Array.isArray(raw)) return [];
  const seen = new Set<string>();
  for (const id of boundedEntries(raw, MAX_LAYOUT_ENTRIES, tally)) {
    if (acceptsColumnId(id, columns) && !seen.has(id)) seen.add(id);
    else tally.dropped++;
  }
  return [...seen];
}

function sanitizeLayout(raw: unknown, columns: ViewColumns | undefined, tally: { dropped: number }): ColumnLayout {
  const layout = asRecord<RawLayout>(raw) ?? {};
  const widths: [string, number][] = [];
  const pins: [string, "left" | "right"][] = [];
  const widthEntries = boundedEntries(Object.entries(asRecord<Record<string, unknown>>(layout.widths) ?? {}), MAX_LAYOUT_ENTRIES, tally);
  for (const [id, width] of widthEntries) {
    if (acceptsColumnId(id, columns) && typeof width === "number" && Number.isFinite(width) && width > 0 && width <= MAX_COLUMN_WIDTH) widths.push([id, width]);
    else tally.dropped++;
  }
  const pinEntries = boundedEntries(Object.entries(asRecord<Record<string, unknown>>(layout.pins) ?? {}), MAX_LAYOUT_ENTRIES, tally);
  for (const [id, side] of pinEntries) {
    if (acceptsColumnId(id, columns) && (side === "left" || side === "right")) pins.push([id, side]);
    else tally.dropped++;
  }
  return {
    widths: Object.fromEntries(widths),
    order: sanitizeIdList(layout.order, columns, tally),
    pins: Object.fromEntries(pins),
    hidden: sanitizeIdList(layout.hidden, columns, tally),
  };
}

/**
 * Checks untrusted view state: unknown shapes, operators, and columns drop, lists and strings are
 * bounded. `dropped` counts every rejected or cut entry so the caller can tell the user; text cut to its limit is not counted.
 */
export function sanitizeViewState(raw: unknown, columns: ViewColumns | undefined): { state: DataGridViewState; dropped: number } {
  const source = asRecord<RawState>(raw);
  if (!source) return { state: emptyViewState(), dropped: 0 };
  const tally = { dropped: 0 };
  const options = asRecord<RawSearchOptions>(source.searchOptions) ?? {};
  return {
    state: {
      sorts: sanitizeSorts(source.sorts, columns, tally),
      filters: sanitizeFilterNodes(source.filters, 0, columns, { leaves: 0, groups: 0 }, tally),
      searchText: typeof source.searchText === "string" ? source.searchText.slice(0, MAX_SEARCH_LENGTH) : "",
      searchOptions: { matchCase: options.matchCase === true, wholeCell: options.wholeCell === true },
      columnLayout: sanitizeLayout(source.columnLayout, columns, tally),
    },
    dropped: tally.dropped,
  };
}

export function cleanViewName(raw: unknown): string {
  return typeof raw === "string" ? raw.trim().slice(0, MAX_VIEW_NAME_LENGTH) : "";
}

/** Reads a stored document, or `null` when `raw` is not a version 1 document. Column ids are not checked here: a view keeps the columns that return later. */
export function parseViewDocument(raw: unknown): DataGridViewsDocument | null {
  const source = asRecord<RawDocument>(raw);
  if (!source || source.version !== 1 || !Array.isArray(source.views)) return null;
  const views: DataGridView[] = [];
  const ids = new Set<string>();
  for (const item of source.views.slice(0, MAX_VIEWS * 2)) {
    if (views.length >= MAX_VIEWS) break;
    const entry = asRecord<RawView>(item);
    const id = entry?.id;
    if (typeof id !== "string" || id === "" || id.length > MAX_VIEW_ID_LENGTH || ids.has(id)) continue;
    const name = cleanViewName(entry?.name);
    if (name === "") continue;
    ids.add(id);
    views.push({ id, name, state: sanitizeViewState(entry?.state, undefined).state });
  }
  const defaultViewId = typeof source.defaultViewId === "string" && ids.has(source.defaultViewId) ? source.defaultViewId : null;
  return { version: 1, defaultViewId, views };
}

/** The text `exportView` returns and `importView` reads. */
export function serializeViewFile(view: Pick<DataGridView, "name" | "state">): string {
  return JSON.stringify({ format: FILE_FORMAT, version: 1, name: view.name, state: view.state });
}

export function parseViewFile(text: string, columns: ViewColumns): ViewFileResult {
  if (text.length > MAX_VIEW_FILE_LENGTH) return { ok: false, reason: "too-large" };
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return { ok: false, reason: "invalid" };
  }
  const file = asRecord<RawFile>(raw);
  if (!file || file.format !== FILE_FORMAT || file.version !== 1 || !asRecord(file.state)) return { ok: false, reason: "invalid" };
  const sanitized = sanitizeViewState(file.state, columns);
  const hidden = new Set(sanitized.state.columnLayout.hidden);
  const sorts = sanitized.state.sorts.filter((s) => !hidden.has(s.columnId));
  const filters = pruneFilterSpecs(sanitized.state.filters, (spec) => !hidden.has(spec.columnId));
  const dropped = sanitized.dropped + (sanitized.state.sorts.length - sorts.length) + (countFilterSpecs(sanitized.state.filters) - countFilterSpecs(filters));
  return { ok: true, name: cleanViewName(file.name), state: { ...sanitized.state, sorts, filters }, dropped };
}

import { MAX_DOCUMENT_LENGTH, type DataGridViewsDocument } from "./view-state";

/**
 * Where saved views live. `load` returns the stored document (any shape; the hook validates it) or
 * `undefined` for none. Throw from `load` when the store cannot be read, so the hook keeps the
 * stored views instead of replacing them. `load` gets a signal that aborts on unmount. `save`
 * receives the whole document and is never aborted, so a save started just before unmount still
 * lands. Both may be sync or async.
 */
export type DataGridViewsStorage = {
  load: (ctx: { signal: AbortSignal }) => unknown | Promise<unknown>;
  save: (document: DataGridViewsDocument) => void | Promise<void>;
};

/** Keeps views for the life of the page. */
export function createMemoryViewsStorage(seed?: DataGridViewsDocument): DataGridViewsStorage {
  let document = seed;
  return {
    load: () => document,
    save: (next) => {
      document = next;
    },
  };
}

function readStorage(): Storage | undefined {
  try {
    return globalThis.localStorage;
  } catch {
    return undefined;
  }
}

const memoryByKey = new Map<string, DataGridViewsDocument>();

/**
 * Stores views as one JSON entry in `localStorage`. When the browser blocks or fills the store,
 * `save` keeps the document in memory for this page and throws, so the hook reports the failure; `load`
 * returns the memory copy until a save succeeds. Malformed text counts as no document; text over the size limit throws.
 * `key` defaults to `"gridcn-views"`.
 */
export function createLocalStorageViewsStorage(key = "gridcn-views"): DataGridViewsStorage {
  return {
    load: () => {
      const unsaved = memoryByKey.get(key);
      if (unsaved) return unsaved;
      let text: string | null | undefined;
      try {
        text = readStorage()?.getItem(key);
      } catch {
        return undefined;
      }
      if (text == null) return undefined;
      if (text.length > MAX_DOCUMENT_LENGTH) throw new Error("The stored views are too large to read");
      try {
        return JSON.parse(text) as unknown;
      } catch {
        return undefined;
      }
    },
    save: (next) => {
      try {
        const store = readStorage();
        if (!store) throw new Error("Browser storage is not available");
        store.setItem(key, JSON.stringify(next));
        memoryByKey.delete(key);
      } catch (cause) {
        memoryByKey.set(key, next);
        throw cause;
      }
    },
  };
}

"use client";

import { useRef, useState, type KeyboardEvent } from "react";
import { Bookmark, Check, Pencil, Star, Trash2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Textarea } from "@/components/ui/textarea";
import { isComposingKey } from "@/registry/default/components/data-grid/data-grid-sdk";
import { useDataGridViews, type ImportViewResult, type UseDataGridViewsOptions } from "./use-data-grid-views";
import { MAX_VIEWS, MAX_VIEW_FILE_LENGTH, MAX_VIEW_NAME_LENGTH, type DataGridView } from "./view-state";

/** User-facing strings of {@link DataGridViews}. */
export type DataGridViewsLabels = {
  views: string;
  modified: string;
  loading: string;
  empty: string;
  loadFailed: string;
  saveFailed: string;
  limit: string;
  overLimit: string;
  importedName: string;
  retry: string;
  setDefault: (name: string) => string;
  unsetDefault: (name: string) => string;
  rename: (name: string) => string;
  delete: (name: string) => string;
  confirmDelete: (name: string) => string;
  newViewName: string;
  saveNew: string;
  updateActive: (name: string) => string;
  confirmRename: string;
  cancel: string;
  fileLabel: string;
  exportView: string;
  importView: string;
  saved: (name: string) => string;
  updated: (name: string) => string;
  renamed: (name: string) => string;
  deleted: (name: string) => string;
  applied: (name: string) => string;
  imported: (name: string, dropped: number) => string;
  exported: string;
  exportTooLarge: string;
  importFailed: (reason: Extract<ImportViewResult, { ok: false }>["reason"]) => string;
};

export const DEFAULT_VIEWS_LABELS: DataGridViewsLabels = {
  views: "Views",
  modified: "Modified",
  loading: "Loading views…",
  empty: "No saved views yet.",
  loadFailed: "Saved views could not be loaded.",
  saveFailed: "Your last change could not be saved.",
  limit: `The limit of ${MAX_VIEWS} views is reached.`,
  overLimit: "The filters, sorts, or search are over the view limits. Shorten them to save the view.",
  importedName: "Imported view",
  retry: "Retry",
  setDefault: (name) => `Use ${name} as the default view`,
  unsetDefault: (name) => `Stop using ${name} as the default view`,
  rename: (name) => `Rename ${name}`,
  delete: (name) => `Delete ${name}`,
  confirmDelete: (name) => `Confirm delete ${name}`,
  newViewName: "View name",
  saveNew: "Save as new view",
  updateActive: (name) => `Update ${name}`,
  confirmRename: "Save name",
  cancel: "Cancel",
  fileLabel: "View as JSON",
  exportView: "Export active view",
  importView: "Import view",
  saved: (name) => `Saved view ${name}`,
  updated: (name) => `Updated view ${name}`,
  renamed: (name) => `Renamed to ${name}`,
  deleted: (name) => `Deleted view ${name}`,
  applied: (name) => `Applied view ${name}`,
  imported: (name, dropped) => (dropped > 0 ? `Imported view ${name}. Left out because they do not fit this grid: ${dropped}.` : `Imported view ${name}`),
  exported: "Exported the active view as JSON below",
  exportTooLarge: "This view is too large to export as text.",
  importFailed: (reason) =>
    reason === "too-large" ? "The text is too long to be a view." : reason === "limit" ? "The view limit is reached." : reason === "loading" ? "Views are still loading." : "The text is not a valid view.",
};

/** Props for {@link DataGridViews}: the options of {@link useDataGridViews} plus styling. */
export type DataGridViewsProps = UseDataGridViewsOptions & {
  className?: string;
  /** Overrides for the menu's strings, merged key by key over the built-in English defaults. The grid's `labels` prop does not reach this menu. */
  labels?: Partial<DataGridViewsLabels>;
};

function ViewRow({
  view,
  active,
  isDefault,
  labels,
  onSelect,
  onSetDefault,
  onRename,
  onDelete,
  onAfterDelete,
}: {
  view: DataGridView;
  active: boolean;
  isDefault: boolean;
  labels: DataGridViewsLabels;
  onSelect: () => void;
  onSetDefault: () => void;
  onRename: (name: string) => void;
  onDelete: () => void;
  onAfterDelete: () => void;
}) {
  const renameButton = useRef<HTMLButtonElement>(null);
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(view.name);
  const [confirming, setConfirming] = useState(false);

  const stopEditing = () => {
    setEditing(false);
    requestAnimationFrame(() => renameButton.current?.focus());
  };
  const commitRename = () => {
    stopEditing();
    if (name.trim() !== "" && name.trim() !== view.name) onRename(name);
  };
  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (isComposingKey(event)) return;
    if (event.key === "Enter") {
      event.preventDefault();
      commitRename();
    } else if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      stopEditing();
    }
  };

  if (editing) {
    return (
      <li className="flex items-center gap-1">
        <Input value={name} maxLength={MAX_VIEW_NAME_LENGTH} aria-label={labels.rename(view.name)} autoFocus onChange={(e) => setName(e.target.value)} onKeyDown={onKeyDown} />
        <Button type="button" size="sm" onClick={commitRename}>
          {labels.confirmRename}
        </Button>
        <Button type="button" size="sm" variant="ghost" onClick={stopEditing}>
          {labels.cancel}
        </Button>
      </li>
    );
  }

  return (
    <li className="flex items-center gap-1" data-active={active ? "" : undefined}>
      <Button type="button" variant={active ? "secondary" : "ghost"} size="sm" className="min-w-0 flex-1 justify-start" aria-current={active ? "true" : undefined} onClick={onSelect}>
        {active ? <Check /> : null}
        <span className="truncate">{view.name}</span>
      </Button>
      <Button type="button" variant="ghost" size="icon-sm" aria-pressed={isDefault} aria-label={isDefault ? labels.unsetDefault(view.name) : labels.setDefault(view.name)} onClick={onSetDefault}>
        <Star className={cn(isDefault && "fill-current")} />
      </Button>
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        ref={renameButton}
        aria-label={labels.rename(view.name)}
        onClick={() => {
          setName(view.name);
          setEditing(true);
        }}
      >
        <Pencil />
      </Button>
      <Button
        type="button"
        variant={confirming ? "destructive" : "ghost"}
        size="icon-sm"
        aria-label={confirming ? labels.confirmDelete(view.name) : labels.delete(view.name)}
        onBlur={() => setConfirming(false)}
        onClick={() => {
          if (!confirming) return setConfirming(true);
          onDelete();
          onAfterDelete();
        }}
      >
        <Trash2 />
      </Button>
    </li>
  );
}

/**
 * Toolbar popover to pick, save, update, rename, delete, default, export, and import grid views.
 * Place it inside the grid provider, for example in `DataGridToolbar`. It takes the options of
 * {@link useDataGridViews}.
 */
export function DataGridViews({ className, labels: labelOverrides, ...options }: DataGridViewsProps) {
  const labels = { ...DEFAULT_VIEWS_LABELS, ...labelOverrides };
  const views = useDataGridViews(options);
  const [newName, setNewName] = useState("");
  const [fileText, setFileText] = useState("");
  const [message, setMessage] = useState({ text: "", id: 0 });
  const [problem, setProblem] = useState("");
  const nameField = useRef<HTMLInputElement>(null);
  const { activeView } = views;
  const announce = (text: string) => {
    setProblem("");
    setMessage((previous) => ({ text, id: previous.id + 1 }));
  };
  const fail = (text: string) => {
    setProblem(text);
    setMessage((previous) => ({ text, id: previous.id + 1 }));
  };
  const focusNameField = () => requestAnimationFrame(() => nameField.current?.focus());
  const atLimit = views.views.length >= MAX_VIEWS;
  const canSave = !views.loading && views.failed !== "load" && !atLimit && !views.overLimit && newName.trim() !== "";

  const save = () => {
    if (!canSave) return;
    const saved = views.saveView(newName);
    if (!saved) return;
    setNewName("");
    announce(labels.saved(saved.name));
  };
  const onSaveKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (isComposingKey(event) || event.key !== "Enter") return;
    event.preventDefault();
    save();
  };
  const runImport = () => {
    const result = views.importView(fileText, { name: labels.importedName });
    if (result.ok) {
      setFileText("");
      announce(labels.imported(result.view.name, result.dropped));
      focusNameField();
    } else {
      fail(labels.importFailed(result.reason));
    }
  };

  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button type="button" variant="outline" size="sm" className={cn("relative", className)} data-modified={views.modified ? "" : undefined}>
            <Bookmark />
            <span className="max-w-40 truncate">{activeView?.name ?? labels.views}</span>
            {views.modified ? <Badge variant="secondary">{labels.modified}</Badge> : null}
          </Button>
        }
      />
      <PopoverContent align="start" className="max-h-(--available-height) w-80 gap-3 overflow-y-auto p-3" aria-label={labels.views}>
        <div data-grid-views="" className="flex flex-col gap-3">
          {views.loading ? <p className="text-muted-foreground">{labels.loading}</p> : null}
          {views.failed ? (
            <div role="alert" className="flex items-center justify-between gap-2 text-destructive">
              <span>{views.failed === "load" ? labels.loadFailed : labels.saveFailed}</span>
              <Button type="button" size="sm" variant="outline" onClick={views.retry}>
                {labels.retry}
              </Button>
            </div>
          ) : null}
          {!views.loading && views.failed !== "load" && views.views.length === 0 ? <p className="text-muted-foreground">{labels.empty}</p> : null}
          {views.views.length > 0 ? (
            <ul className="flex flex-col gap-1" aria-label={labels.views}>
              {views.views.map((view) => (
                <ViewRow
                  key={view.id}
                  view={view}
                  active={view.id === views.activeViewId}
                  isDefault={view.id === views.defaultViewId}
                  labels={labels}
                  onSelect={() => {
                    views.selectView(view.id);
                    announce(labels.applied(view.name));
                  }}
                  onSetDefault={() => views.setDefaultView(view.id === views.defaultViewId ? null : view.id)}
                  onRename={(name) => {
                    if (views.renameView(view.id, name)) announce(labels.renamed(name.trim()));
                  }}
                  onDelete={() => {
                    if (views.deleteView(view.id)) announce(labels.deleted(view.name));
                  }}
                  onAfterDelete={focusNameField}
                />
              ))}
            </ul>
          ) : null}
          {activeView && views.modified ? (
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={views.overLimit}
              onClick={() => {
                if (views.updateView()) {
                  announce(labels.updated(activeView.name));
                  focusNameField();
                }
              }}
            >
              {labels.updateActive(activeView.name)}
            </Button>
          ) : null}
          <div className="flex items-center gap-1">
            <Input ref={nameField} value={newName} maxLength={MAX_VIEW_NAME_LENGTH} placeholder={labels.newViewName} aria-label={labels.newViewName} onChange={(e) => setNewName(e.target.value)} onKeyDown={onSaveKeyDown} />
            <Button type="button" size="sm" disabled={!canSave} onClick={save}>
              {labels.saveNew}
            </Button>
          </div>
          <div className="flex flex-col gap-1.5">
            <Textarea
              value={fileText}
              onChange={(e) => setFileText(e.target.value)}
              maxLength={MAX_VIEW_FILE_LENGTH * 2}
              aria-label={labels.fileLabel}
              spellCheck={false}
              rows={4}
              className="max-h-40 resize-y font-mono text-xs"
            />
            <div className="flex items-center gap-1">
              <Button
                type="button"
                variant="outline"
                size="sm"
                disabled={!activeView}
                onClick={() => {
                  const text = views.exportView();
                  if (text === null) return fail(labels.exportTooLarge);
                  setFileText(text);
                  announce(labels.exported);
                }}
              >
                {labels.exportView}
              </Button>
              <Button type="button" variant="outline" size="sm" disabled={fileText.trim() === ""} onClick={runImport}>
                {labels.importView}
              </Button>
            </div>
          </div>
          {atLimit ? <p className="text-muted-foreground">{labels.limit}</p> : null}
          {views.overLimit ? <p className="text-muted-foreground">{labels.overLimit}</p> : null}
          {problem ? <p className="text-destructive">{problem}</p> : null}
          <p role="status" className="sr-only">
            {/* a trailing no-break space on every second message makes a repeated text change, so it is announced again */}
            {message.text}
            {message.id % 2 === 0 ? " " : ""}
          </p>
        </div>
      </PopoverContent>
    </Popover>
  );
}
